#!/usr/bin/env python3
"""zip-password-finder - Find the password of protected ZIP files"""

import argparse
import sys
import os
import time
import zipfile
import itertools
import string
import threading
from concurrent.futures import ThreadPoolExecutor, as_completed

# Character sets
CHARSETS = {
    'l': string.ascii_lowercase,
    'u': string.ascii_uppercase,
    'd': string.digits,
    'h': '0123456789abcdef',
    'H': '0123456789ABCDEF',
    's': ' !\"#$%&\'()*+,-./:;<=>?@[\\]^_`{|}~ '
}

def generate_passwords(chars, min_len, max_len, starting_password=None):
    """Generate passwords from charset with given length range"""
    if starting_password:
        if len(starting_password) < min_len:
            return []
        if len(starting_password) > max_len:
            return [starting_password]
        # Generate passwords starting from starting_password
        for length in range(len(starting_password), max_len + 1):
            for combo in itertools.product(chars, repeat=length - len(starting_password)):
                yield starting_password + ''.join(combo)
    else:
        for length in range(min_len, max_len + 1):
            for combo in itertools.product(chars, repeat=length):
                yield ''.join(combo)

def test_password(zip_path, password, file_number=0):
    """Test if a password opens the ZIP file"""
    try:
        with zipfile.ZipFile(zip_path, 'r') as zf:
            if file_number >= 0:
                if file_number < len(zf.namelist()):
                    zf.read(zf.namelist()[file_number], pwd=password.encode() if isinstance(password, str) else password)
                else:
                    return False
            else:
                zf.read(zf.namelist()[0], pwd=password.encode() if isinstance(password, str) else password)
            return True
    except (zipfile.BadZipFile, zipfile.BadZipfile, RuntimeError, Exception):
        return False

def dictionary_attack(zip_path, dictionary_path, file_number=0):
    """Attack using a dictionary file"""
    try:
        with open(dictionary_path, 'r') as f:
            for password in f:
                password = password.strip()
                if test_password(zip_path, password, file_number):
                    return password
    except Exception as e:
        print(f"Error reading dictionary: {e}", file=sys.stderr)
    return None

def brute_force_attack(zip_path, charset, min_len, max_len, file_number=0, starting_password=None):
    """Brute force attack using charset"""
    chars = CHARSETS.get(charset)
    if chars is None:
        return None

    for password in generate_passwords(chars, min_len, max_len, starting_password):
        if test_password(zip_path, password, file_number):
            return password
    return None

def worker(zip_path, dictionary_path, charset, min_len, max_len, file_number, starting_password, results, lock):
    """Worker function for multi-threaded attack"""
    password = None

    if dictionary_path and os.path.exists(dictionary_path):
        password = dictionary_attack(zip_path, dictionary_path, file_number)
        if password:
            with lock:
                results['password'] = password
                results['method'] = 'dictionary'
                results['elapsed'] = time.time() - results['start']
            return

    if charset:
        password = brute_force_attack(zip_path, charset, min_len, max_len, file_number, starting_password)
        if password:
            with lock:
                results['password'] = password
                results['method'] = 'brute_force'
                results['elapsed'] = time.time() - results['start']
            return

    with lock:
        results['password'] = None
        results['method'] = 'none'
        results['elapsed'] = time.time() - results['start']

def main():
    parser = argparse.ArgumentParser(description='Find the password of protected ZIP files')
    parser.add_argument('zip_file', help='Path to the ZIP file')
    parser.add_argument('-d', '--dictionary', help='Path to dictionary file')
    parser.add_argument('-c', '--charset', help='Character set to use (l, u, d, h, H, s)')
    parser.add_argument('-m', '--min-length', type=int, default=1, help='Minimum password length')
    parser.add_argument('-M', '--max-length', type=int, default=8, help='Maximum password length')
    parser.add_argument('-f', '--file-number', type=int, default=0, help='File number to test (0 for first file, -1 for all)')
    parser.add_argument('-s', '--starting-password', help='Starting password for brute force')
    parser.add_argument('-t', '--threads', type=int, default=4, help='Number of threads')
    parser.add_argument('--version', action='version', version='%(prog)s 1.0')

    args = parser.parse_args()

    if not os.path.exists(args.zip_file):
        print(f"Error: ZIP file '{args.zip_file}' not found", file=sys.stderr)
        sys.exit(1)

    if args.dictionary and not os.path.exists(args.dictionary):
        print(f"Error: Dictionary file '{args.dictionary}' not found", file=sys.stderr)
        sys.exit(1)

    if args.charset and args.charset not in CHARSETS:
        print(f"Error: Invalid charset '{args.charset}'", file=sys.stderr)
        sys.exit(1)

    results = {'password': None, 'method': None, 'elapsed': 0}
    results['start'] = time.time()

    if args.dictionary and os.path.exists(args.dictionary):
        password = dictionary_attack(args.zip_file, args.dictionary, args.file_number)
        if password:
            print(f"Password found: {password}")
            print(f"Method: dictionary")
            print(f"Time: {time.time() - results['start']:.2f}s")
            sys.exit(0)

    if args.charset:
        password = brute_force_attack(args.zip_file, args.charset, args.min_length, args.max_length, args.file_number, args.starting_password)
        if password:
            print(f"Password found: {password}")
            print(f"Method: brute_force")
            print(f"Time: {time.time() - results['start']:.2f}s")
            sys.exit(0)

    print("No password found", file=sys.stderr)
    sys.exit(1)

if __name__ == '__main__':
    main()
